from store.text import normalize


def enable_trigram(apps, schema_editor):
    # Busca aproximada por nome usa pg_trgm; em SQLite a busca cai para Python.
    if schema_editor.connection.vendor == 'postgresql':
        schema_editor.execute('CREATE EXTENSION IF NOT EXISTS pg_trgm')


def fill_search_name(apps, schema_editor):
    Product = apps.get_model('store', 'Product')
    for product in Product.objects.select_related('category'):
        product.search_name = normalize(f'{product.name} {product.category.name}')
        product.save(update_fields=['search_name'])


